const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/expenses');
await p.waitForTimeout(500);
const rowSel = id => `tr[data-id="${id}"]`;
// approve e10 (Elin Fors), first button = approve
await p.locator(rowSel('e10')+' .k6tmr6t').nth(0).click();
await p.waitForTimeout(600);
// reject e3 (Per Åberg), second button = reject
await p.locator(rowSel('e3')+' .k6tmr6t').nth(1).click();
await p.waitForTimeout(600);
await p.reload(); await p.waitForTimeout(500);
const rows = await p.$$eval('tbody tr', trs => trs.map(t => t.dataset.id+' | '+t.querySelector('.st').textContent+' | '+t.children[4].textContent));
console.log(rows.join('\n'));
await b.close();
EOF
